/* @lc app=leetcode id=2242 lang=kotlin */
class Solution { fun maximumScore(A: IntArray, edges: Array<IntArray>): Int = Array(A.size) { java.util.PriorityQueue<Int>(compareBy { A[it] }) }.apply { edges.forEach { e -> this[e[0]].add(e[1]).run { if (this[e[0]].size > 3) this[e[0]].poll() }.run { this[e[1]].add(e[0]) }.run { if (this[e[1]].size > 3) this[e[1]].poll() } } }.let { top -> edges.fold(-1) { res, e -> maxOf(res, top[e[0]].fold(-1) { r1, u -> maxOf(r1, top[e[1]].fold(-1) { r2, v -> if (u != e[1] && v != e[0] && u != v) maxOf(r2, A[e[0]] + A[e[1]] + A[u] + A[v]) else r2 }) }) } } }